contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes4 interfaceId) public payable {
        bool ok;
        bool result;

        // 0xffffffff must never be reported as supported (ERC-165 rule).
        try c.supportsInterface(0xffffffff) returns (bool r) {
            ok = true;
            result = r;
        } catch {
            ok = false;
        }

        bool iface165;
        bool ok165;
        try c.supportsInterface(type(IERC165).interfaceId) returns (bool r) {
            ok165 = true;
            iface165 = r;
        } catch {
            ok165 = false;
        }

        bool ifaceAC;
        bool okAC;
        try c.supportsInterface(type(IAccessControl).interfaceId) returns (bool r) {
            okAC = true;
            ifaceAC = r;
        } catch {
            okAC = false;
        }

        assert(!ok || result == false);
        assert(ok165 && iface165);
        assert(okAC && ifaceAC);
    }
}

