        c = _c;
    }

    function run(bytes4 interfaceId) public payable {
        (bool success, bytes memory data) = address(c).staticcall(abi.encodeWithSelector(c.supportsInterface.selector, interfaceId));
        bool completed = success && data.length >= 32;
        bool result = completed && abi.decode(data, (bool));
        bool expected = (interfaceId == type(IERC165).interfaceId);
        assert(!completed || result == expected);
    }

    receive() external payable {}
}

